暖身練習：單一 Promise 處理
請實作一個名為 doublePromiseValue 的非同步箭頭函式。
該函式會接收一個名為 numberPromise 的參數（這是一個會 resolve 出數字的 Promise）。
請取得該 Promise 解析後的數值，將其乘以 2，並回傳計算結果。
const doublePromiseValue = async (numberPromise) =&gt; {
  // 請在此處完成實作
};

// 測試預期行為：
// const myPromise = new Promise(resolve =&gt; setTimeout(() =&gt; resolve(10), 100));
// doublePromiseValue(myPromise).then(result =&gt; console.log(result)); 
// 預期輸出: 20



const doublePromiseValue = async (numberPromise) =&gt; {
  const result = await numberPromise();
  console.log("result", result * 2);
  return result * 2;
};

// 測試預期行為：
const myPromise = new Promise((resolve) =&gt; setTimeout(() =&gt; resolve(10), 100));
doublePromiseValue(myPromise).then((result) =&gt; console.log(result));
// 預期輸出: 20
